CREATE TYPE user_role AS ENUM ('student','staff','admin');
CREATE TYPE patient_kind AS ENUM ('student');
CREATE TYPE appointment_status AS ENUM ('scheduled','completed','cancelled');
CREATE TABLE users (id SERIAL PRIMARY KEY,username VARCHAR(20) UNIQUE NOT NULL,password_hash TEXT NOT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(25),role user_role NOT NULL DEFAULT 'patient',is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE departments (id SERIAL PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,description TEXT);
CREATE TABLE patients (id SERIAL PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,patient_type patient_kind NOT NULL,college_department VARCHAR(120),date_of_birth DATE,gender VARCHAR(30),address TEXT,emergency_contact VARCHAR(100));
CREATE TABLE doctors (id SERIAL PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,employee_id VARCHAR(30) UNIQUE NOT NULL,department_id INTEGER NOT NULL REFERENCES departments(id) ON DELETE RESTRICT,specialization VARCHAR(150) NOT NULL,qualification VARCHAR(150),experience INTEGER CHECK(experience >= 0));
CREATE TABLE doctor_availability (id SERIAL PRIMARY KEY,doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,day_of_week VARCHAR(10) NOT NULL CHECK(day_of_week IN ('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday')),start_time TIME NOT NULL,end_time TIME NOT NULL,CHECK(end_time>start_time),UNIQUE(doctor_id,day_of_week,start_time,end_time));
CREATE TABLE appointments (id SERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE RESTRICT,doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,reason TEXT NOT NULL,status appointment_status NOT NULL DEFAULT 'scheduled',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(doctor_id,appointment_date,appointment_time));
CREATE TABLE prescriptions (id SERIAL PRIMARY KEY,appointment_id INTEGER UNIQUE REFERENCES appointments(id) ON DELETE SET NULL,doctor_id INTEGER REFERENCES doctors(id),staff_id INTEGER REFERENCES users(id),patient_id INTEGER NOT NULL REFERENCES patients(id),diagnosis TEXT NOT NULL,medicines TEXT NOT NULL,instructions TEXT,prescription_notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE notices (id SERIAL PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX appointments_patient_idx ON appointments(patient_id,appointment_date); CREATE INDEX appointments_doctor_idx ON appointments(doctor_id,appointment_date);
